(()=>{const zh=document.documentElement.lang.startsWith('zh'),keys=['Kd','logRate','concentration'],defaults={Kd:10,logRate:0,concentration:10},get=k=>document.getElementById('C06-'+k);let state={};function update(){const kd=+get('Kd').value,rate=+get('logRate').value,c=+get('concentration').value,on=2e5*10**rate,off=on*kd*1e-9,eq=120*c/(kd+c),obs=on*c*1e-9+off,end=eq*(-Math.expm1(-obs*180));state={Kd:kd,logRate:rate,concentration:c,equilibrium_RU:eq,endpoint_RU:end,half_life_s:Math.log(2)/off,kon_M_inv_s_inv:on,koff_s_inv:off};keys.forEach(k=>get(k+'-value').textContent=(+get(k).value).toFixed(1));get('result').textContent=(zh?'平衡响应：':'Equilibrium: ')+eq.toFixed(2)+' RU; '+(zh?'180 s 响应：':'Response at 180 s: ')+end.toFixed(2)+' RU; '+(zh?'解离半衰期：':'Dissociation half-life: ')+state.half_life_s.toFixed(2)+' s';const X=t=>75+t/600*635,Y=r=>305-r/120*250;let out='<rect width="760" height="380" fill="#fcfbf7"/><path d="M75 45V305H710" fill="none" stroke="#61758a"/>';for(let y=0;y<=120;y+=30)out+='<line x1="75" x2="710" y1="'+Y(y)+'" y2="'+Y(y)+'" stroke="#dce3e5"/><text x="65" y="'+(Y(y)+4)+'" font-size="12" text-anchor="end">'+y+'</text>';for(let t=0;t<=600;t+=120)out+='<text x="'+X(t)+'" y="327" text-anchor="middle" font-size="12">'+t+'</text>';out+='<path d="M75 '+Y(eq)+'H710" stroke="#37967d" stroke-dasharray="5 4"/><path d="M'+X(180)+' 45V305" stroke="#a7b4bd" stroke-dasharray="3 4"/><path d="'+Array.from({length:601},(_,t)=>{const r=t<=180?eq*(-Math.expm1(-obs*t)):end*Math.exp(-off*(t-180));return(t?'L':'M')+X(t).toFixed(2)+' '+Y(r).toFixed(2)}).join(' ')+'" fill="none" stroke="#167d9a" stroke-width="2.5"/>';out+='<text x="80" y="25" font-size="13">'+(zh?'结合响应 / RU':'Binding response / RU')+'</text><text x="395" y="355" text-anchor="middle" font-size="13">'+(zh?'时间 / s；180 s 开始冲洗':'Time / s; wash begins at 180 s')+'</text>';get('plot').innerHTML=out;}function set(p){keys.forEach(k=>{if(p[k]!==undefined){const e=get(k);e.value=Math.max(+e.min,Math.min(+e.max,+p[k]));}});update();}keys.forEach(k=>get(k).addEventListener('input',update));get('reset').addEventListener('click',()=>set(defaults));window.CourseLab={set,state:()=>({...state}),reset:()=>set(defaults)};update();})();
